#!/usr/bin/env ruby
# frozen_string_literal: true

require "fileutils"
require "json"
require "erb"

root_dir = File.expand_path("../", __dir__)
path = Dir.glob("#{root_dir}/ts/cocofix/.tool_coverages.json").first
output_path = "#{__dir__}/lib/turboscan/suggested_fix.rb"

tools = JSON.load(File.read(path))
rules_per_tool = tools.transform_values do |languages|
  languages.transform_values do |rules|
    rules.keys
  end.values.flatten.sort
end

generator_script = File.basename(__FILE__)
template = <<-RUBY
# frozen_string_literal: true

# Code generated by <%= generator_script %>, DO NOT EDIT.

module Turboscan
  module SuggestedFix
    ENABLED_TOOLS = %w[
      <%= tools.keys.join("\n      ") %>
    ].freeze

    SUPPORTED_RULES_PER_TOOL = {
<% rules_per_tool.each do |tool, supported_rules| -%>
      "<%= tool %>" => %w[
        <%= supported_rules.join("\n        ") %>
      ].freeze,

<% end -%>
    }
    # rubocop:enable Metrics/CollectionLiteralLength
  end
end
RUBY

File.open(output_path, "w") do |file|
  file.write ERB.new(template, trim_mode: "-").result(binding)
end
